1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}
9	 * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased
10	 * first three letters of the last name and NNNN is a per-city 4-digit zero-padded
11	 * sequence equal to one more than the number of owners already in that city (e.g.
12	 * {@code SYD-SMI-0007}). Runs before the owner is saved, so the count excludes the owner
13	 * being created and successive creates in the same city receive consecutive sequence
14	 * numbers.
15	 */
